29	/**
30	 * The fragment, or the whole page around it. A view in a folder of its own
31	 * (home/index) is named by its path. `layout` is the layout's own data (the
32	 * live channel, the bar's count), `regions` what a cold load of an overlay
33	 * puts in its region ({ modal: { html, location } }), and `system` asks for
34	 * the folder's design system instead of ds/v1 (pages ported from a design).
35	 */
36	export function shaped(view, data, { fragment, path, title, layout = {}, regions = {}, system = false }) {
37	  const body = render(view.includes('/') ? `./${view}` : `./_${view}`, data);
38	  if (fragment) return body;
39	  return render('./layout', { body, path, title, layout, regions, system });
40	}
